"""
Classes:

- :class:`L3`: start L3
- :class:`L2`: start L2
"""

# TODO: Update module docstring

from taf.internal.managedobject import ManagedObject
from .exceptions import (EdaemonSetupFailure,
                         EgateSetupFailure,
                         L3SetupFailure,
                         L2SetupFailure)
from .remote_entities import RemoteProcess, RemoteService
from .logger import logger


class AirPhoneRemoteProcess(ManagedObject):
    """ Edaemon.
    Methods:
    - :meth:`setup`: prepares and starts edaemon process
    """
    # TODO: Rewrite class docstring
    # TODO: Method docstrings

    def __init__(self, ssh_connection, l2, directory, port, *args, **kwargs):
        super(AirPhoneRemoteProcess, self).__init__(**kwargs)
        self.add_prerequisite(ssh_connection)
        if l2 is not None:
            self.add_prerequisite(l2)

        command = self.COMMAND_TEMPLATE.format(port=port)

        self._process = RemoteProcess(ssh_connection, command, directory,
                                      sudo=self.WITH_SUDO)
        self.logger = logger.getChild(self.__class__.__name__)
        self._process.logger = self.logger

    def _setup(self):
        self._process.kill()
        exit_code, _, _ = self._process.start(wait=self.WAIT_FOR_EXEC_END)
        if exit_code != 0:
            exc_msg = "{} failed to initialize.".format(self.COMMON_NAME)
            raise self.SETUP_FAILURE_EXCEPTION(exc_msg)
        log_msg = "{} startup done.".format(self.COMMON_NAME)
        self.logger.info(log_msg)

    def _teardown(self):
        self.logger.debug('Tearing down {}'.format(self.COMMON_NAME))
        self._process.kill()

    def read_output(self):
        return self._process.read_output()

    def read_error(self):
        return self._process.read_error()


class Edaemon(AirPhoneRemoteProcess):
    """ Edaemon.
    Methods:
    - :meth:`setup`: prepares and starts edaemon process
    """
    # NOTE: This process uses sudo as a command prefix.
    COMMAND_TEMPLATE = './edaemon --port {port}'
    COMMON_NAME = "Edaemon"
    SETUP_FAILURE_EXCEPTION = EdaemonSetupFailure
    WITH_SUDO = True
    WAIT_FOR_EXEC_END = True

    # TODO: Rewrite class docstring


class Egate(AirPhoneRemoteProcess):
    """ This class manages (runs / kills) Egate process on a remote host.
    Methods:
    - :meth:`setup`: kill Egate process running on the previously specified
    port and start a new one from scratch.
    """
    COMMAND_TEMPLATE = './egate --root --port {port}'
    COMMON_NAME = "Egate"
    SETUP_FAILURE_EXCEPTION = EgateSetupFailure
    WITH_SUDO = False
    WAIT_FOR_EXEC_END = True

    # TODO: Update class docstring.


class L3(AirPhoneRemoteProcess):
    COMMAND_TEMPLATE = './l3 {port}'
    COMMON_NAME = "L3"
    SETUP_FAILURE_EXCEPTION = L3SetupFailure
    WITH_SUDO = False
    WAIT_FOR_EXEC_END = False

    # TODO: Class docstring


class L2(ManagedObject):
    SERVICE_NAME = 'ccs_mix'

    # TODO: Class docstring
    # TODO: Method docstrings

    def __init__(self, ssh_connection, *args, **kwargs):
        super(L2, self).__init__(**kwargs)
        self.add_prerequisite(ssh_connection)

        self._service = RemoteService(ssh_connection, self.SERVICE_NAME)
        self.logger = logger.getChild(self.__class__.__name__)
        self._service.logger = self.logger

    def _setup(self):
        self._check_ccs_mix_state()
        self.logger.info("L2 setup done.")

    def _check_ccs_mix_state(self):
        service_active = self._service.is_active()
        if not service_active:
            exc_msg = "Restarting service {} failed."
            exc_msg = exc_msg.format(self.SERVICE_NAME)
            raise L2SetupFailure(exc_msg)
